import{_ as o,l as s,o as e,c as i,v as t,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Karatsuba","description":"","frontmatter":{"title":"Karatsuba","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/karatsuba.md","filePath":"cs/karatsuba.md","lastUpdated":1789023840000}'),u={name:"cs/karatsuba.md"};function h(b,a,m,_,T,f){const n=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="karatsuba" tabindex="-1">Karatsuba <a class="header-anchor" href="#karatsuba" aria-label="Permalink to &quot;Karatsuba&quot;">​</a></h1><div class="epigraph"><p>把 $n$ 位数拆成两半，三次 $n/2$ 乘代替四次：$T(n)=3T(n/2)+O(n)$，即 $O(n^{\\log_2 3})$。</p><footer>—— 据 Karatsuba and Ofman, Multiplication of Multidigit Numbers on Automata, 1962；CLRS 第 4、30 章整理</footer></div><p>上一课<a href="/cs/bignum-arith">高精度算术</a>小学乘 \\(O(n^2)\\)。卷积 \\(xy\\) 看似要四块交叉乘。缺口是 Karatsuba：用一次加减换掉一次乘。不重写进位规则。后课 FFT 把次数再降。Toom–Cook 点名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(x=a B^{m}+b\\)，\\(y=c B^{m}+d\\)，\\(m=n/2\\)。小学：\\(ac,ad,bc,bd\\) 四次乘。Karatsuba：\\(p=ac\\)，\\(q=bd\\)，\\(r=(a+b)(c+d)\\)，则 \\(ad+bc=r-p-q\\)。三次递归乘 + \\(O(n)\\) 加减。主定理 \\(T(n)=3T(n/2)+O(n)=\\Theta(n^{\\log_2 3})\\approx n^{1.585}\\)。</p><p>缺口是这次代数恒等式，不是 FFT 的单位根。</p><h3 id="小-切回小学" tabindex="-1">小 \\(n\\) 切回小学 <a class="header-anchor" href="#小-切回小学" aria-label="Permalink to &quot;小 $n$ 切回小学&quot;">​</a></h3><p>递归到阈值以下用 \\(O(n^2)\\)，常数才好看。阈值依机器。不要对 20 位整数硬套三层递归。</p><p><span class="marginnote">Karatsuba 1962（与 Ofman）。Toom–Cook 把拆成 \\(k\\) 段、\\(2k-1\\) 次乘。后课 FFT/Schönhage–Strassen 近线性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对齐偶数位。递归。注意 \\(a+b\\) 可能多一位。符号另行处理，对绝对值乘。</p>',11)),(e(),l(p,null,{default:r(()=>[c(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20XY%5B%22x%2C%20y%20%E5%AF%B9%E5%8D%8A%22%5D%20--%3E%20P%5B%22ac%2C%20bd%2C%20(a%2Bb)(c%2Bd)%22%5D%0A%20%20P%20--%3E%20REC%5B%22%E4%B8%89%E6%AC%A1%E9%80%92%E5%BD%92%22%5D%0A%20%20REC%20--%3E%20COMB%5B%22%E7%A7%BB%E4%BD%8D%E7%9B%B8%E5%8A%A0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>并行三次乘可，本课串行计数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>恒等式把交叉项合成一次乘。与<a href="/cs/divide-conquer">分治</a>同形。正确性是多项式恒等，与基 \\(B\\) 无关。减法可能借位，高精度课已会。</p><p>Strassen 矩阵乘是另一恒等式，后课。不要混。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 FFT 乘。负数、模乘可先乘再模。后课默认：大整数乘至少 Karatsuba 阈值策略。下一课 FFT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三次半长乘代替四次，\\(O(n^{1.585})\\)。</li><li>小规模切回小学。</li><li>代数恒等式，不是近似。</li><li>出处：Karatsuba and Ofman, 1962。</li></ul>',8))])}const A=o(u,[["render",h]]);export{B as __pageData,A as default};
